INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('cd', 'CD Pendiente', '🏥', 'Confirmaciones diagnósticas pendientes de agendamiento o respuesta.', '81.2% de los casos tiene gestión registrada — 44 sin gestión.', '20 RUT distintos se repiten dentro de este módulo (posibles duplicados).', 10, '[{"t":"Fecha de ingreso futura","c":102,"sev":"serious"},{"t":"Atención posterior al ingreso","c":50,"sev":"critical"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('pacienteep', 'Paciente Derivado EP', '🧑‍⚕️', 'Pacientes derivados a Evaluación Preventiva (EP) desde otros servicios.', '100.0% de los casos tiene gestión registrada.', 'No se detectaron RUT repetidos en este módulo.', 10, '[{"t":"Fecha de ingreso futura","c":4,"sev":"serious"},{"t":"Atención posterior al ingreso","c":1,"sev":"critical"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('reembolsos', 'Reembolsos', '💳', 'Solicitudes de reembolso de gastos médicos particulares.', '99.3% de los casos tiene gestión registrada — 2 sin gestión.', '33 RUT distintos se repiten dentro de este módulo (posibles duplicados).', 14, '[{"t":"Fecha de ingreso futura","c":34,"sev":"serious"}]'::jsonb);
INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('informes', 'Informes Médicos', '📄', 'Solicitudes de informes, certificados y licencias médicas.', '19.2% de los casos tiene gestión registrada.', '167 RUT distintos se repiten dentro de este módulo (posibles duplicados).', 10, '[{"t":"Atención posterior al ingreso","c":168,"sev":"critical"},{"t":"Fecha de ingreso futura","c":89,"sev":"serious"}]'::jsonb);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', '551 solicitudes sin gestión registrada', 'De las 2615 solicitudes analizadas, 551 no tienen ninguna evidencia de que alguien las haya trabajado.', 'Priorizar el cierre de estos casos partiendo por los más antiguos. A futuro, hacer obligatorio dejar una nota de gestión antes de poder cerrar o archivar una solicitud.', 0);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', 'Atención registrada después del ingreso (376 casos)', 'La fecha de atención debería ser siempre anterior a la fecha en que se ingresó el caso. Cuando aparece al revés, normalmente indica que se escribió mal una de las dos fechas.', 'Revisar caso a caso en la sección de inconsistencias de cada módulo.', 1);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('serious', '328 RUT que se repiten dentro de un mismo módulo', 'Puede ser un paciente que pidió lo mismo varias veces, o un caso duplicado que ya se atendió y se volvió a registrar por error.', 'Revisar los grupos de RUT repetido antes de gestionar un caso nuevo.', 2);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('serious', '27 RUT mal escritos', 'Registros con RUT vacío, con formato raro, o con un dígito verificador que no corresponde al número.', 'Corregir estos casos en la base — el detalle exacto está disponible en la pestaña Auditoría de RUT.', 3);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('warning', 'Al menos 6 filas de prueba mezcladas con datos reales', 'Se detectaron registros como "Prueba" o RUT "1234" mezclados entre las solicitudes reales.', 'Eliminar o marcar claramente estas filas como "prueba" para que no se cuenten en las estadísticas.', 4);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('warning', 'Calidad de la redacción: 673 solicitudes "Regular" y 23 "Deficiente"', 'Al revisar cómo quedó escrita la descripción de cada solicitud, algunas quedaron poco claras o muy cortas como para entender qué pide el paciente.', 'Pedir al equipo que, al registrar el detalle, escriba al menos una frase completa y clara.', 5);
